@pytest.mark.parametrize('command,schema', [('seed-calls', 'scar.call-source-seeds'), ('link-calls', 'scar.call-links-envelope')]) @pytest.mark.parametrize('hardlink', [False, True]) def test_unresolved_captured_source_is_protected_even_if_it_looks_like_a_report(tmp_path, command, schema, hardlink): project = tmp_path / 'project' project.mkdir() # This dict expression is both valid Python and valid JSON. Python code # filenames need not end in .py; source-budget failure must not hide it. source = project / 'module.json' original = json.dumps({'schema': schema}).encode() source.write_bytes(original) entry = project / 'entry.py' entry.write_text(f'exec(compile(open({str(source)!r}).read(), {str(source)!r}, "exec"), {{}})\n') trace = tmp_path / 'trace' capture = cli('trace', '--calls-only', '--project-root', project, '--out', trace, '--', sys.executable, entry, cwd=project) assert capture.returncode == 0, capture.stdout + capture.stderr destination = tmp_path / 'source-alias.json' if hardlink else source if hardlink: os.link(source, destination) rejected = cli(command, trace, '--project-root', project, '--out', destination, '--max-call-source-bytes', 1) > assert rejected.returncode == 2, rejected.stdout + rejected.stderr E AssertionError: {"status": "SOURCE_SEEDS", "summary": {"counts": {"processes": 1, "files": 3, "code_captures": 4, "entered_code_groups": 4, "entered_invocations": 4, "eligible_groups": 0, "eligible_codes": 0, "issues": 0}, "caller_connections_established": false, "data_connections_established": false, "effects_established": false, "function_environment_established": false, "transformation_authorized": false}, "out": "/tmp/scar-d0-output-regression/test_unresolved_captured_sourc0/project/module.json", "transformation_authorized": false} E E assert 0 == 2 E + where 0 = CompletedProcess(args=['/home/zyf/miniconda3/envs/lewm/bin/python', '-m', 'scar.cli', 'seed-calls', '/tmp/scar-d0-outp...put-regression/test_unresolved_captured_sourc0/project/module.json", "transformation_authorized": false}\n', stderr='').returncode
